/*
* You can use any libraries imported in Flowise
* You can use properties specified in Input Variables with the prefix $. For example: $foo
* You can get default flow config: $flow.sessionId, $flow.chatId, $flow.chatflowId, $flow.input, $flow.state
* You can get global variables: $vars.<variable-name>
* Must return a string value at the end of function
*/

const fetch = require('node-fetch');
const url = 'https://api.open-meteo.com/v1/forecast?latitude=52.52&longitude=13.41&current_weather=true';
const options = {
    method: 'GET',
    headers: {
        'Content-Type': 'application/json'
    }
};
try {
    const response = await fetch(url, options);
    const text = await response.text();
    return text;
} catch (error) {
    console.error(error);
    return '';
}

inputs.customFunctionJavascriptFunction:
// === GUARDARRAIL (devuelve objeto)

// 1) Normaliza la entrada
const pick = (o, keys) => { for (const k of keys) if (o && typeof o[k]==="string" && o[k].trim()) return o[k]; return ""; };
let raw = "";
if (typeof $input === "string") raw = $input;
else if ($input && typeof $input === "object") raw = pick($input, ["text","question","prompt","user_input","message","input"]);
raw = String(raw || "").trim();

const text  = raw;
const lower = text.toLowerCase();

// 2) Deny-list (jailbreaks obvios)
const denylist = [
  /ignore\s+previous\s+instructions/,
  /disregard\s+all\s+prior\s+instructions/,
  /reveal\s+the\s+system\s+prompt/,
  /show\s+your\s+hidden\s+instructions/,
  /\bjailbreak\b/, /bypass\s+safety/,
  /act\s+as\s+dan\b/, /developer\s+mode/,
  /pretend\s+the\s+rules\s+do\s+not\s+apply/
];
const hitJailbreak = denylist.find(rx => rx.test(lower));

// 3) PII (ES): IBAN bloquea; DNI/email/tel enmascarar
const re = {
  iban:  /\bES\d{22}\b/i,
  dni:   /\b\d{8}[A-HJ-NP-TV-Z]\b/i,
  email: /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/,
  tel:   /\b(?:\+34\s?)?(?:6|7|8|9)\d{8}\b/
};
const hasIBAN = re.iban.test(text);
const masked  = text.replace(re.dni,"DNI[****]").replace(re.email,"EMAIL[****]").replace(re.tel,"TEL[****]");

// 4) Decisión (por defecto permitir)
const allow = !(hitJailbreak || hasIBAN);

// 5) Objeto de salida + payload de auditoría
const block_pattern = hitJailbreak ? String(hitJailbreak) : (hasIBAN ? "IBAN" : "");
const audit_payload = JSON.stringify({
  allow, block_pattern, texto: masked,
  prompt_version: $flow.state.prompt_version || "v1.0",
  index_version:   $flow.state.index_version   || "",
  trace_id:        $flow.state.trace_id        || "",
  conversation_id: $flow.state.conversation_id || "",
  timestamp: new Date().toISOString()
});

return { allow, block_pattern, user_text: masked, audit_payload };

